package com.library.book; import com.baomidou.mybatisplus.core.mapper.BaseMapper; import org.apache.ibatis.annotations.*; import java.util.*; @Mapper public interface BookMapper extends BaseMapper<Book>{@Select("SELECT b.*,c.name category_name,p.name publisher_name FROM book b LEFT JOIN book_category c ON b.category_id=c.id LEFT JOIN publisher p ON b.publisher_id=p.id WHERE b.deleted=0 AND (#{keyword}='' OR b.title LIKE CONCAT('%',#{keyword},'%') OR b.isbn LIKE CONCAT('%',#{keyword},'%') OR b.author_name LIKE CONCAT('%',#{keyword},'%')) ORDER BY b.id DESC LIMIT #{offset},#{size}")List<Map<String,Object>> search(@Param("keyword")String keyword,@Param("offset")long offset,@Param("size")long size);@Select("SELECT COUNT(*) FROM book WHERE deleted=0 AND (#{keyword}='' OR title LIKE CONCAT('%',#{keyword},'%') OR isbn LIKE CONCAT('%',#{keyword},'%') OR author_name LIKE CONCAT('%',#{keyword},'%'))")long countSearch(String keyword);}

